entries[32721] = { ["name"] = "Rationen der Himmelswache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenötigt Stufe 55\nBenötigt Himmelswache der Sha'tari\n- Wohlwollend\nBenutzen: Stellt im Verlauf von 30 Sek. 6000 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 15 Ausdauer und 15 Willenskraft.\nVerkaufspreis:" }
entries[32722] = { ["name"] = "Angereicherter Terozapfensaft", ["text"] = "Einzigartig (20)\nBenötigt Stufe 65\nBenötigt Himmelswache der Sha'tari\n- Freundlich\nBenutzen: Stellt im Verlauf von 30 Sek. 4320 Gesundheit und 5100 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\nVerkaufspreis:" }
