entries[32724] = { ["name"] = "Schlickbedecktes Objekt", ["text"] = "Wird beim Aufheben gebunden\n\"Welch wundersame Schätze mögen wohl unter dem Schlick verborgen sein?\"\n<Zum Öffnen rechtsklicken>" }
