entries[32761] = { ["name"] = "Die Offizierskugel", ["text"] = "Wird beim Aufheben gebunden\nMunition\n53 Schaden Tempo 3.00\n(17.67 Schaden pro Sekunde)\nBenötigt Stufe 70\n\"Mächtiges Badabumm.\"\nVerkaufspreis:" }
entries[32762] = { ["name"] = "Rulksters Hirnsaft", ["text"] = "Benötigt Stufe 55\nBenutzen: Stellt 1800 to 3000 Mana wieder her. (1 Min Abklingzeit)\n\"Sei kein Dummkopf, trink deinen Hirnsaft!\"\nVerkaufspreis:" }
entries[32763] = { ["name"] = "Rulksters Geheimsoße", ["text"] = "Benötigt Stufe 55\nBenutzen: Stellt 1500 to 2500 Gesundheit wieder her. (1 Min Abklingzeit)\n\"Trinkt und lebt.\"\nVerkaufspreis:" }
entries[32764] = { ["name"] = "Flaschataurens himmlisches Gebräu", ["text"] = "Benötigt Stufe 65\nBenutzen: Erhöht 1 Stunde lang die maximale Gesundheit um 500 und die Ausweichwertung um 10. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Der Effekt hält auch nach dem Tode an. (3 Sek. Abklingzeit)\n\"Die flaschenhafte Essenz des mythenumrankten Wesens!\"\nVerkaufspreis:" }
entries[32765] = { ["name"] = "Flaschataurens Tränen", ["text"] = "Benötigt Stufe 65\nBenutzen: Erhöht die Angriffskraft 1 Stunde lang um 120. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Der Effekt hält auch nach dem Tode an. (3 Sek. Abklingzeit)\n\"Die destillierten Tränen des schwer zu fassenden Flaschatauren.\"\nVerkaufspreis:" }
entries[32766] = { ["name"] = "Flaschataurens Fläschchen der Flaschität", ["text"] = "Benötigt Stufe 65\nBenutzen: Erhöht die Willenskraft 1 Stunde lang um 62. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\n\"Trägt das Zeichen des Flaschatauren.\"\nVerkaufspreis:" }
entries[32767] = { ["name"] = "Flaschataurens Fläschchen der ziemlich beeindruckenden Macht", ["text"] = "Benötigt Stufe 50\nBenutzen: Erhöht die Zaubermacht 1 Stunde lang um 70. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\n\"Nicht überragend, aber auch nicht so schlecht.\"\nVerkaufspreis:" }
entries[32768] = { ["name"] = "Zügel des Rabenfürsten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 40\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein riesiges Rabenreittier oder gibt es wieder frei." }
